#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    string reversePrefix(string word, char ch) {
        auto pos = word.find(ch);
        if (pos != string::npos) {
            reverse(word.begin(), word.begin() + pos + 1);
        }
        return word;
    }
};

class Solution {
    public String reversePrefix(String word, char ch) {
        int idx = word.indexOf(ch);
        if (idx == -1) return word;
        return new StringBuilder(word.substring(0, idx + 1)).reverse().toString() + word.substring(idx + 1);
    }
}

var reversePrefix = function(word, ch) {
    const idx = word.indexOf(ch);
    if (idx === -1) return word;
    const prefixRev = word.slice(0, idx + 1).split('').reverse().join('');
    return prefixRev + word.slice(idx + 1);
};
